typedef struct { sqlite3_int64 id; char name[64]; int age; } Person;

int person_save(sqlite3 *db, Person *p) {
    const char *sql = p->id == 0
        ? "INSERT INTO person(name, age) VALUES(?, ?)"
        : "UPDATE person SET name = ?, age = ? WHERE id = ?";
    sqlite3_stmt *st = NULL;
    if (sqlite3_prepare_v2(db, sql, -1, &st, NULL) != SQLITE_OK) return -1;
    sqlite3_bind_text(st, 1, p->name, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 2, p->age);
    if (p->id != 0) sqlite3_bind_int64(st, 3, p->id);
    int rc = sqlite3_step(st);
    if (rc == SQLITE_DONE && p->id == 0) p->id = sqlite3_last_insert_rowid(db);
    sqlite3_finalize(st);
    return rc == SQLITE_DONE ? 0 : -1;
}
